function debounce(e,i){var s;return function(){clearTimeout(s),s=setTimeout(e,i)}}var $win=$(window);$win.load(function(){new Swiper(".swiper-clients",{speed:5e3,autoplay:1,autoplayDisableOnInteraction:!1,grabCursor:!0,slidesPerView:5,spaceBetween:50,loop:!0,breakpoints:{1024:{slidesPerView:4,spaceBetween:50},992:{slidesPerView:3,spaceBetween:40},768:{slidesPerView:3,spaceBetween:30},600:{slidesPerView:2,spaceBetween:30},480:{slidesPerView:1,spaceBetween:0}}}),new Swiper(".swiper-testimonials",{speed:1e3,autoplay:1e4,slidesPerView:1,loop:!0})}),$win.on("resize orientationchange",debounce(function(){if(swiper)try{swiper.update(!0),swiper.stopAutoplay&&swiper.stopAutoplay(),swiper.startAutoplay&&swiper.startAutoplay()}catch(e){}},200));